package in.suniye.app;
import android.Manifest;
import android.app.Activity;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.hardware.camera2.*;
import android.hardware.camera2.params.StreamConfigurationMap;
import android.media.Image;
import android.media.ImageReader;
import android.os.*;
import android.util.Size;
import android.view.*;
import android.widget.*;
import java.nio.ByteBuffer;
import java.util.Arrays;
public final class CameraActivity extends Activity {
    private VoiceControls voice;private TextureView preview;private TextView status;private Button shutter;private CameraDevice camera;private CameraCaptureSession session;private volatile ImageReader images;private HandlerThread thread;private Handler worker;private ReaderController reader;private int orientation=90;private volatile boolean active=false;private boolean taking=false,opening=false;private volatile long cameraEpoch=0;private final Handler mainHandler=new Handler(Looper.getMainLooper());private String cameraId;private Size previewSize=new Size(1280,720);
    @Override public void onCreate(Bundle b){super.onCreate(b);reader=SuniyeApp.reader(this);voice=new VoiceControls(this,reader,command->{if(command==VoiceCommand.CAPTURE||command==VoiceCommand.READ){take();}else if(command==VoiceCommand.STOP){reader.stop();finish();}else reader.announce("चित्र लेने के लिए फोटो लो बोलें।");});LinearLayout controls=Ui.column(this);shutter=Ui.button(this,"चित्र लेकर सुनिए",true);controls.addView(shutter,new LinearLayout.LayoutParams(-1,-2));shutter.setOnClickListener(v->take());Button stop=Ui.button(this,"रोकिए",false);Button speak=Ui.button(this,"बोलिए",false);speak.setContentDescription("बोलिए। फोटो लो या रोकिए बोलें।");speak.setOnClickListener(v->voice.open());LinearLayout row=new LinearLayout(this);LinearLayout.LayoutParams first=new LinearLayout.LayoutParams(0,-2,1);first.rightMargin=Ui.dp(this,8);row.addView(stop,first);row.addView(speak,new LinearLayout.LayoutParams(0,-2,1));Ui.add(controls,row,-2,12);stop.setOnClickListener(v->{reader.stop();finish();});LinearLayout root=Ui.screenWithControls(this,controls);Ui.add(root,Ui.text(this,"कागज़ पढ़िए",28,Ui.INK,true),-2,0);Ui.add(root,Ui.text(this,"पास और रोशनी में रखें।",18,Ui.INK,false),-2,8);preview=new TextureView(this);LinearLayout.LayoutParams previewLayout=new LinearLayout.LayoutParams(-1,0,1);previewLayout.topMargin=Ui.dp(this,16);root.addView(preview,previewLayout);status=Ui.text(this,"",22,Ui.INK,false);status.setVisibility(View.GONE);Ui.add(root,status,-2,12);
        preview.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){open();}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){transform(w,h);}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){close();return true;}public void onSurfaceTextureUpdated(SurfaceTexture t){}});}
    @Override protected void onResume(){super.onResume();active=true;taking=false;shutter.setEnabled(true);thread=new HandlerThread("paper-camera");thread.start();worker=new Handler(thread.getLooper());if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},10);else if(preview.isAvailable())open();}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==VoiceControls.MICROPHONE_REQUEST){voice.permissionResult(code,results);return;}if(code==10&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED){if(preview.isAvailable())open();}else fail("कैमरे की अनुमति परिवार का सदस्य चालू करे।");}
    private void open(){if(!active||opening||camera!=null||worker==null||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;final long epoch=cameraEpoch;opening=true;try{CameraManager manager=getSystemService(CameraManager.class);for(String id:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(id);Integer facing=c.get(CameraCharacteristics.LENS_FACING);if(facing!=null&&facing==CameraCharacteristics.LENS_FACING_BACK){Integer sensor=c.get(CameraCharacteristics.SENSOR_ORIENTATION);orientation=sensor==null?90:sensor;StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);if(map==null)continue;Size[] sizes=map.getOutputSizes(SurfaceTexture.class);previewSize=choose(sizes);Size jpeg=choose(map.getOutputSizes(ImageFormat.JPEG));cameraId=id;images=ImageReader.newInstance(jpeg.getWidth(),jpeg.getHeight(),ImageFormat.JPEG,2);images.setOnImageAvailableListener(this::received,worker);break;}}
            if(cameraId==null){fail("इस फ़ोन में पीछे का कैमरा नहीं मिला।");return;}manager.openCamera(cameraId,new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){if(!active||epoch!=cameraEpoch){c.close();return;}opening=false;camera=c;startPreview();}public void onDisconnected(CameraDevice c){c.close();if(epoch==cameraEpoch&&camera==c){opening=false;camera=null;fail("कैमरा बंद हुआ। फिर खोलें।",epoch);}}public void onError(CameraDevice c,int error){c.close();if(epoch==cameraEpoch){opening=false;if(camera==c)camera=null;fail("कैमरा अभी नहीं खुल रहा। फिर कोशिश करें।",epoch);}}},mainHandler);
        }catch(Exception e){opening=false;fail("कैमरा अभी नहीं खुल रहा। फिर कोशिश करें।",epoch);}}
    private Size choose(Size[] sizes){if(sizes==null||sizes.length==0)throw new IllegalArgumentException("No camera output sizes");Size best=sizes[0];for(Size s:sizes)if(Math.max(s.getWidth(),s.getHeight())<=1920&&(Math.max(best.getWidth(),best.getHeight())>1920||s.getWidth()*s.getHeight()>best.getWidth()*best.getHeight()))best=s;return best;}
    private void startPreview(){final long epoch=cameraEpoch;final CameraDevice owned=camera;try{SurfaceTexture texture=preview.getSurfaceTexture();if(texture==null)return;texture.setDefaultBufferSize(previewSize.getWidth(),previewSize.getHeight());Surface surface=new Surface(texture);CaptureRequest.Builder request=camera.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);request.addTarget(surface);request.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);camera.createCaptureSession(Arrays.asList(surface,images.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){if(!active||epoch!=cameraEpoch||camera!=owned){s.close();return;}session=s;try{s.setRepeatingRequest(request.build(),null,worker);runOnUiThread(()->transform(preview.getWidth(),preview.getHeight()));}catch(Exception e){fail("कैमरा फिर खोलें।");}}public void onConfigureFailed(CameraCaptureSession s){s.close();fail("कैमरा फिर खोलें।",epoch);}},mainHandler);}catch(Exception e){fail("कैमरा फिर खोलें।");}}
    private void transform(int width,int height){if(width==0||height==0)return;Matrix matrix=new Matrix();RectF view=new RectF(0,0,width,height);RectF buffer=new RectF(0,0,previewSize.getHeight(),previewSize.getWidth());buffer.offset(view.centerX()-buffer.centerX(),view.centerY()-buffer.centerY());matrix.setRectToRect(view,buffer,Matrix.ScaleToFit.FILL);float scale=Math.max((float)height/previewSize.getWidth(),(float)width/previewSize.getHeight());matrix.postScale(scale,scale,view.centerX(),view.centerY());preview.setTransform(matrix);}
    private void take(){final long epoch=cameraEpoch;if(camera==null||session==null||taking){fail("कैमरा तैयार होने दें।");return;}taking=true;shutter.setEnabled(false);status.setVisibility(View.VISIBLE);status.setText("चित्र ले रहे हैं।");try{CaptureRequest.Builder r=camera.createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);r.addTarget(images.getSurface());r.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);r.set(CaptureRequest.JPEG_ORIENTATION,orientation);session.capture(r.build(),new CameraCaptureSession.CaptureCallback(){@Override public void onCaptureFailed(CameraCaptureSession s,CaptureRequest r,CaptureFailure f){fail("चित्र नहीं लिया। फिर दबाएँ।",epoch);}},mainHandler);}catch(Exception e){fail("चित्र नहीं लिया। फिर दबाएँ।");}}
    private void received(ImageReader source){final long epoch=cameraEpoch;if(!active||source!=images)return;byte[] bytes;try(Image image=source.acquireLatestImage()){if(image==null)return;ByteBuffer data=image.getPlanes()[0].getBuffer();bytes=new byte[data.remaining()];data.get(bytes);}catch(Exception e){fail("चित्र नहीं खुला। फिर लें।");return;}if(!active||epoch!=cameraEpoch)return;runOnUiThread(()->{if(!active||epoch!=cameraEpoch||source!=images)return;reader.readImage(()->{Bitmap bitmap=ImageDecoder.decodeBitmap(ImageDecoder.createSource(ByteBuffer.wrap(bytes)),(decoder,info,s)->{decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);int w=info.getSize().getWidth(),h=info.getSize().getHeight();if(Math.max(w,h)>1600)decoder.setTargetSize(w*1600/Math.max(w,h),h*1600/Math.max(w,h));});long total=0;int samples=0;for(int y=0;y<bitmap.getHeight();y+=24)for(int x=0;x<bitmap.getWidth();x+=24){int p=bitmap.getPixel(x,y);total+=(Color.red(p)+Color.green(p)+Color.blue(p))/3;samples++;}if(samples==0||total/samples<25){bitmap.recycle();throw new UserMessage("बहुत अँधेरा है। रोशनी में दोबारा चित्र लें।");}return bitmap;});startActivity(new android.content.Intent(this,MainActivity.class).setAction(MainActivity.SHOW_READING).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK|android.content.Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});}
    private void fail(String message){fail(message,cameraEpoch);}
    private void fail(String message,long epoch){runOnUiThread(()->{if(!active||epoch!=cameraEpoch)return;opening=false;taking=false;if(status!=null){status.setVisibility(View.VISIBLE);status.setText(message);}if(shutter!=null)shutter.setEnabled(true);reader.announce(message);});}
    private void close(){opening=false;cameraId=null;if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(images!=null){images.close();images=null;}}
    @Override protected void onStop(){voice.close();super.onStop();}
    @Override protected void onPause(){if(!voice.permissionPending())voice.close();active=false;cameraEpoch++;close();if(thread!=null){thread.quitSafely();thread=null;worker=null;}super.onPause();}
}
